(7606199, 1229956, 3306, '<td valign="top">Nicely composed. The colors are terrific.</td>', 'Nicely composed. The colors are terrific.', '2018-12-27 06:47:27.000000', NULL, 1),
(7606200, 1230030, 3306, '<td valign="top">The picture is really good but the title doesnt seem to match since the subject is on the rocks with a tripod. It would be more believable if he were picking up broken pieces! The light on the distant mountain is awesome.</td>', 'The picture is really good but the title doesnt seem to match since the subject is on the rocks with a tripod. It would be more believable if he were picking up broken pieces! The light on the distant mountain is awesome.', '2018-12-27 06:50:44.000000', NULL, 1),
(7606201, 1229982, 3306, '<td valign="top">Nice moody shot and good composition.</td>', 'Nice moody shot and good composition.', '2018-12-27 06:51:26.000000', NULL, 1),
(7606202, 1229994, 3306, '<td valign="top">Well done. I like the lighting. I think I would have taken the diamond on the front right out of the picture. Its not as clear in focus and a little blown out.</td>', 'Well done. I like the lighting. I think I would have taken the diamond on the front right out of the picture. Its not as clear in focus and a little blown out.', '2018-12-27 06:53:56.000000', NULL, 1),
